    Ascore = 0
    Bscore = 0
    prev = ''
    for i in lst:
        if i == 'A':
            Ascore += 1
            if prev == 'A':
                Ascore += 1
        elif i == 'B':
            Bscore += 1
            if prev == 'B':
                Bscore += 1
        prev = i
        if Ascore >= n:
            return 'A'
        elif Bscore >= n:
            return 'B'
    if Ascore < n and Bscore < n:
        return None
```

